"""Synthetic prestack SEG-Y fixtures for probe **P7**.

Six geometries, one generator, one seed. Each fixture is a small regular gather volume
whose index headers are exactly the ones an MDIO prestack template binds by name.

Why this module exists at all
-----------------------------
Every prestack template MDIO ships binds its dimensions **by trace-header field name**,
and the names it wants — ``cable``, ``channel``, ``gun``, ``sail_line``, ``shot_line``,
``receiver``, ``offset``, ``cdp`` — are not names the SEG-Y rev 1 standard uses. Two of
them exist in rev 1 under a different name at a byte position the industry agrees on
(``offset`` is byte 37, "distance from source point to receiver group"; ``cdp`` is byte
21, "ensemble number"); the rest are acquisition-specific and every vendor places them
where it likes.

So a prestack fixture is not just a trace layout. It is a trace layout **plus a
declaration of where those fields live**, and the declaration has to be carried with the
file — which is what :class:`PrestackGeometry` does and why :func:`prestack_spec` exists.

Determinism
-----------
Everything here is a pure function of the arguments. No clock, no unseeded RNG, no
environment. Two calls with the same arguments produce byte-identical files, asserted by
a test rather than assumed. The two upstream hazards documented in
``tests/fixtures/generators/poststack3d.py`` apply unchanged and are handled the same
way: ``SegyFactory.create_textual_header()`` with no argument embeds ``datetime.now()``,
and it neither pads nor validates, so explicit 40x80 text is passed and the encoded
result is checked to be exactly 3200 bytes.
"""

from __future__ import annotations

import itertools
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import numpy as np
from segy.factory import SegyFactory
from segy.schema import ScalarType
from segy.schema.header import HeaderField

from sdip._pins import (
    SEGY_BINARY_HEADER_BYTES as BINARY_HEADER_BYTES,
)
from sdip._pins import (
    SEGY_TEXTUAL_HEADER_BYTES as TEXTUAL_HEADER_BYTES,
)
from sdip.spec.generator import build_gap_free_spec

DEFAULT_SEED = 20260822
"""Fixed seed, from the pre-registration. Committed, so a stranger reproduces the file."""

TEXT_ROWS, TEXT_COLS = 40, 80
"""The rev 1 textual header is exactly 40 rows of 80 columns, EBCDIC, 3200 bytes."""

PLANT_FIELD = "device_trace_id"
"""Where the seeded per-trace tag goes: byte 213, ``int16``, declared by rev 1.

No prestack template binds it, so it is inert as far as the conversion is concerned, and
a distinct seeded value per trace makes a dropped or transposed trace visible in the
header alone. This is the prestack counterpart of the planted bytes 233-240 in
``poststack3d.py``; those bytes cannot be used here because several geometries need them
for their index fields.
"""

TRACE_BUDGET = 500
"""Per-fixture trace ceiling from the pre-registration. P7 probes shape, not scale."""

_TEXT_LINES: tuple[str, ...] = (
    "C 1 SDIP SYNTHETIC FIXTURE - PRESTACK GATHERS - PROBE P7",
    "C 2 GENERATED BY tests/fixtures/generators/prestack.py",
    "C 3 NO PROPRIETARY OR RESTRICTED DATA - SPECIFICATION 6.6 IS BINDING",
    "C 4 AMPLITUDES ARE ANALYTIC: ORDINAL*4 + T*0.25, EXACT IN FLOAT32",
    "C 5 INDEX HEADERS ARE DECLARED BY THE GEOMETRY, NOT BY THE REV 1 STANDARD",
    "C 6 BYTE 213 CARRIES A SEEDED PER-TRACE TAG NO TEMPLATE BINDS",
    "C 7 THIS HEADER CONTAINS NO TIMESTAMP, BY DESIGN",
)


def deterministic_text(rows: int = TEXT_ROWS, cols: int = TEXT_COLS) -> str:
    """Textual header content: fixed, correctly shaped, and carrying **no timestamp**.

    See ``poststack3d.deterministic_text`` for the two measured upstream behaviours that
    make this necessary. Both still apply; neither is worked around, both are avoided.
    """
    lines = [line[:cols].ljust(cols) for line in _TEXT_LINES[:rows]]
    lines += ["C".ljust(cols)] * (rows - len(lines))
    return "\n".join(lines)


DETERMINISTIC_TEXT: str = deterministic_text()
"""The committed textual header for every fixture in this module."""


@dataclass(frozen=True, slots=True)
class IndexField:
    """One trace-header field a prestack template binds, and where this fixture puts it.

    ``rationale`` is not decoration. These byte positions are a **choice**, and a choice
    a reader cannot audit is indistinguishable from an accident. It records what the
    rev 1 standard puts at those bytes and why the field displaced it.
    """

    name: str
    byte: int
    fmt: ScalarType
    rationale: str

    def header_field(self) -> HeaderField:
        """The ``segy`` declaration for this field."""
        return HeaderField(name=self.name, byte=self.byte, format=self.fmt)


@dataclass(frozen=True, slots=True)
class Axis:
    """One axis of the fixture's regular trace layout.

    Args:
        name: How derived columns refer to this axis.
        values: The values it takes, in order. The trace order is the cartesian product
            of the axes, outermost first — which is also the order a real acquisition
            writes them.
        write: ``True`` when ``name`` is itself a trace-header field to be written.
            ``False`` for a pure counting axis whose header value is produced by a
            :class:`DerivedColumn` instead — flip-flop shot numbering needs this,
            because ``shot_point`` depends on both the shot counter and the gun.
    """

    name: str
    values: tuple[int, ...]
    write: bool = True


@dataclass(frozen=True, slots=True)
class DerivedColumn:
    """A trace-header column computed from axis **indices**, not axis values.

    ``value = base + sum(index_of(axis) * step)``. Indices rather than values so that a
    coordinate stays inside ``int32`` no matter how the axis is numbered.
    """

    name: str
    axes: tuple[str, ...]
    base: int
    steps: tuple[int, ...] = ()


@dataclass(frozen=True, slots=True)
class PrestackGeometry:
    """One prestack geometry: its template, its index fields, and its trace layout."""

    name: str
    template: str
    index_fields: tuple[IndexField, ...]
    axes: tuple[Axis, ...]
    derived: tuple[DerivedColumn, ...]
    store_dimensions: tuple[str, ...]
    note: str
    n_samples: int = 32
    sample_interval_us: int = 4000
    revision: int = 1

    @property
    def trace_count(self) -> int:
        """Traces the cartesian product of the axes produces."""
        total = 1
        for axis in self.axes:
            total *= len(axis.values)
        return total

    @property
    def declared_names(self) -> tuple[str, ...]:
        """Names this geometry adds to the rev 1 standard spec."""
        return tuple(f.name for f in self.index_fields)


def _shot_flip_flop(base: int) -> tuple[DerivedColumn, ...]:
    """Flip-flop shot numbering: gun 1 takes the even shots, gun 2 the odd ones.

    This is the ``Type B`` geometry MDIO's ``ShotWrappingStrategy`` detects, and it is
    the realistic one — a dual-source vessel interleaves shot points between guns. It is
    chosen deliberately rather than avoided: Type B is the branch that **derives a new
    ``shot_index`` dimension** that appears nowhere in the source file, which is exactly
    the kind of thing this probe exists to find.
    """
    return (
        DerivedColumn("shot_point", ("shot", "gun"), base, (2, 1)),
        DerivedColumn("orig_field_record_num", ("shot", "gun"), base + 4000, (2, 1)),
    )


