GEOMETRY_NAMES: tuple[str, ...] = tuple(g.name for g in GEOMETRIES)
"""The geometry table, in order. The probe transcribes this and a test pins the two."""

_BY_NAME: dict[str, PrestackGeometry] = {g.name: g for g in GEOMETRIES}


def geometry(name: str) -> PrestackGeometry:
    """Look one geometry up by name.

    Args:
        name: A member of :data:`GEOMETRY_NAMES`.

    Returns:
        The geometry descriptor.

    Raises:
        KeyError: If the name is not in the table.
    """
    return _BY_NAME[name]


def prestack_spec(geom: PrestackGeometry) -> Any:
    """A gap-free rev 1 spec with the geometry's index fields declared.

    Built by :func:`sdip.spec.generator.build_gap_free_spec` and then customised through
    ``segy``'s own public ``HeaderSpec.customize``, which removes any standard field the
    new declaration overlaps. Byte coverage is therefore preserved exactly — a field
    displaced is a field replaced, never a field dropped — so the result is still
    gap-free.

    **This function does not assert that.** G1 is run by the caller, on purpose: an
    assertion written by the thing it judges is not an assertion (see
    ``sdip/spec/gate.py``).

    Args:
        geom: The geometry whose index fields to declare.

    Returns:
        The customised ``SegySpec``.
    """
    built = build_gap_free_spec(geom.revision)
    spec = built.segy_spec
    spec.trace.header.customize([f.header_field() for f in geom.index_fields])
    return spec


@dataclass(frozen=True, slots=True)
class PrestackSegy:
    """A generated prestack SEG-Y and the ground truth it was built from."""

    path: Path
    geometry: PrestackGeometry
    columns: dict[str, np.ndarray] = field(default_factory=dict)
    amplitudes: np.ndarray = field(default_factory=lambda: np.zeros(0, dtype=np.float32))
    planted: np.ndarray = field(default_factory=lambda: np.zeros(0, dtype=np.int16))
    textual_header: bytes = b""
    binary_header: bytes = b""

    @property
    def name(self) -> str:
        """The geometry name."""
        return self.geometry.name

    @property
    def template(self) -> str:
        """The MDIO template this fixture is built for."""
        return self.geometry.template

    @property
    def trace_count(self) -> int:
        """Number of traces written."""
        return self.geometry.trace_count

    @property
    def samples_per_trace(self) -> int:
        """Samples per trace."""
        return self.geometry.n_samples

    @property
    def byte_size(self) -> int:
        """Size of the written file."""
        return self.path.stat().st_size

    def spec(self) -> Any:
        """The customised gap-free spec this file must be read with."""
        return prestack_spec(self.geometry)


def _axis_indices(geom: PrestackGeometry) -> dict[str, np.ndarray]:
    """Per-trace index along every axis, for the cartesian trace order."""
    ranges = [range(len(axis.values)) for axis in geom.axes]
    grid = np.array(list(itertools.product(*ranges)), dtype=np.int64)
    return {axis.name: grid[:, position] for position, axis in enumerate(geom.axes)}


def _columns(geom: PrestackGeometry) -> dict[str, np.ndarray]:
    """Every trace-header column this geometry writes, as int64 arrays."""
    indices = _axis_indices(geom)
    columns: dict[str, np.ndarray] = {}

    for axis in geom.axes:
        if axis.write:
            columns[axis.name] = np.asarray(axis.values, dtype=np.int64)[indices[axis.name]]

    for column in geom.derived:
        total = np.full(geom.trace_count, column.base, dtype=np.int64)
        for axis_name, step in zip(column.axes, column.steps, strict=True):
            total = total + indices[axis_name] * step
        columns[column.name] = total

    return columns


def _amplitudes(n_traces: int, n_samples: int) -> np.ndarray:
    """Analytic amplitudes, exactly representable in float32.

    ``ordinal * 4 + t * 0.25``: every value is a small multiple of a power of two, so
    float32 holds it with no rounding and the comparison can be exact equality — which
    is what Plane 4 demands and what a saved buffer could not give (Appendix A.4.2).
    Distinct per trace, so a transposition shows up in the samples as well as the header.
    """
    ordinal = np.arange(n_traces, dtype=np.float32).reshape(-1, 1)
    t = np.arange(n_samples, dtype=np.float32).reshape(1, -1)
    return (ordinal * 4.0 + t * 0.25).astype(np.float32)


def make_prestack(
    geom: PrestackGeometry,
    path: str | Path,
    *,
    seed: int = DEFAULT_SEED,
    text: str = DETERMINISTIC_TEXT,
) -> PrestackSegy:
    """Write one deterministic synthetic prestack SEG-Y.

    Args:
        geom: The geometry to build.
        path: Where to write the file.
        seed: Seed for the per-trace tag in :data:`PLANT_FIELD`. Fixed and committed.
        text: Textual header content. Passing ``None`` is **not** supported: the upstream
            default embeds a timestamp and would make the fixture non-deterministic.

    Returns:
        The file plus the ground truth it was built from.

    Raises:
        ValueError: If the encoded textual or binary header is not its mandated length.
    """
    target = Path(path)
    spec = prestack_spec(geom)
    factory = SegyFactory(
        spec,
        sample_interval=geom.sample_interval_us,
        samples_per_trace=geom.n_samples,
    )

    n_traces = geom.trace_count
    columns = _columns(geom)
    amplitudes = _amplitudes(n_traces, geom.n_samples)

    rng = np.random.default_rng(seed)
    planted = rng.integers(1, 32_768, size=n_traces, dtype=np.int16)

    headers = factory.create_trace_header_template(size=n_traces)
    samples = factory.create_trace_sample_template(size=n_traces)

    headers["coordinate_scalar"][:] = 1
    headers["trace_seq_num_line"][:] = np.arange(1, n_traces + 1)
    headers[PLANT_FIELD][:] = planted
    for name, values in columns.items():
        headers[name][:] = values
    samples[:] = amplitudes

    textual_header = factory.create_textual_header(text)
    if len(textual_header) != TEXTUAL_HEADER_BYTES:
        msg = (
            f"textual header encoded to {len(textual_header)} bytes, must be "
            f"{TEXTUAL_HEADER_BYTES}. Upstream does not pad or validate: a short text "
            f"silently produces a malformed SEG-Y with every later offset wrong."
        )
        raise ValueError(msg)
    binary_header = factory.create_binary_header()
    if len(binary_header) != BINARY_HEADER_BYTES:  # pragma: no cover - upstream invariant
        msg = f"binary header encoded to {len(binary_header)} bytes, must be {BINARY_HEADER_BYTES}"
        raise ValueError(msg)

    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(textual_header + binary_header + factory.create_traces(headers, samples))

    return PrestackSegy(
        path=target,
        geometry=geom,
        columns=columns,
        amplitudes=amplitudes,
        planted=np.asarray(planted),
        textual_header=textual_header,
        binary_header=binary_header,
    )


def build_fixture(name: str, path: str | Path) -> PrestackSegy:
    """Build one geometry by name.

    Args:
        name: A member of :data:`GEOMETRY_NAMES`.
        path: Where to write the file.

    Returns:
        The generated fixture.
    """
    return make_prestack(geometry(name), path)
